class XAPI_API_CallAutomator
{

    str bearerToken;
    str tenantId = XAPI_AutomationHelper::tenantId;
    str clientId = XAPI_AutomationHelper::clientId;
    str clientSecret = XAPI_AutomationHelper::clientSecret;
    str resourceUrl = XAPI_AutomationHelper::resourceUrl;
    Num logNum;
}

Method.Source:
private str GetAccessToken()
{
    System.Net.HttpWebRequest request;
    System.Net.HttpWebResponse response;
    System.IO.StreamWriter streamWriter;
    System.IO.StreamReader streamReader;
    str url = "https://login.microsoftonline.com/" + tenantId + "/oauth2/token";
    str responseText;
    System.Text.RegularExpressions.Regex regex;
    System.Text.RegularExpressions.Match match;

    System.Uri uri = new System.Uri("http://dummy"); // helper for encoding
    str encodedSecret = System.Net.WebUtility::UrlEncode(clientSecret);
    str postData = "grant_type=client_credentials"
       + "&client_id=" + clientId
       + "&client_secret=" + encodedSecret
       + "&resource=" + resourceUrl;

    try
    {
        request = System.Net.WebRequest::Create(url) as System.Net.HttpWebRequest;
        request.set_Method("POST");
        request.set_ContentType("application/x-www-form-urlencoded");

        streamWriter = new System.IO.StreamWriter(request.GetRequestStream());
        streamWriter.Write(postData);
        streamWriter.Flush();
        streamWriter.Close();

        response = request.GetResponse() as System.Net.HttpWebResponse;
        streamReader = new System.IO.StreamReader(response.GetResponseStream());
        responseText = streamReader.ReadToEnd();
        streamReader.Close();

    }
    catch (Exception::CLRError)
    {
        System.Exception ex = CLRInterop::getLastException();
        System.Net.WebException webEx;
        System.IO.StreamReader errorReader;
        str errorText = "";

        if (ex is System.Net.WebException)
        {
            webEx = ex as System.Net.WebException;

            if (webEx.get_Response())
            {
                errorReader = new System.IO.StreamReader(webEx.get_Response().GetResponseStream());
                errorText = errorReader.ReadToEnd();
                errorReader.Close();
            }
        }
        return "";
    }

    regex = new System.Text.RegularExpressions.Regex("\"access_token\"\\s*:\\s*\"([^\"]+)\"");
    match = regex.Match(responseText);

    if (match.Success)
    {
        return match.Groups.get_Item(1).get_Value();
    }

    return "";
}

public str sendPostRequest(str url, str json)
{
    if (strLen(bearerToken) == 0)
    {
        bearerToken = this.GetAccessToken();

        if (strLen(bearerToken) == 0)
        {
            return '';
        }
    }

    System.Net.HttpWebRequest request;
    System.Net.HttpWebResponse response;
    System.IO.StreamWriter streamWriter;
    System.IO.StreamReader streamReader;


    try
    {
        request = System.Net.WebRequest::Create(url) as System.Net.HttpWebRequest;
        request.set_Method("POST");
        request.set_ContentType("application/json");

        request.get_Headers().Set("Authorization", "Bearer " + bearerToken);

        streamWriter = new System.IO.StreamWriter(request.GetRequestStream());
        streamWriter.Write(json);
        streamWriter.Flush();
        streamWriter.Close();

        response = request.GetResponse() as System.Net.HttpWebResponse;
        streamReader = new System.IO.StreamReader(response.GetResponseStream());

        str responseText = streamReader.ReadToEnd();
        streamReader.Close();
        return responseText;
    }
    catch (Exception::CLRError)
    {
        System.Exception ex = CLRInterop::getLastException();
        System.Net.WebException webEx;
        System.IO.StreamReader errorReader;
        str errorText = "";

        if (ex is System.Net.WebException)
        {
            webEx = ex as System.Net.WebException;

            if (webEx.get_Response() != null)
            {
                errorReader = new System.IO.StreamReader(webEx.get_Response().GetResponseStream());
                errorText = errorReader.ReadToEnd();
                errorReader.Close();
            }
        }

    }

    return '';
}

public void callCreateCustAPI()
{
    DimensionAttribute        da;
    DimensionAttributeValue   dv;

    select firstonly name from da
    order by da.Name asc
    join DisplayValue from dv
    where dv.DimensionAttribute == da.RecId;

    Map configMap = new Map(Types::String, Types::String);
    configMap.insert('<DataAreaId>', curExt());
    configMap.insert('<AlternativeCustomerNumber>', '195108224444');
    configMap.insert('<DimensionName>', da.Name);   
    configMap.insert('<DimensionValue>', dv.DisplayValue);

    var body = this.prepareBody(XAPI_APIS::CreateCustomer, configMap);
    str responseTxt = this.sendPostRequest(resourceUrl + "/api/services/EGS_WebApiServiceAPI/EGS_WebApiSeServiceAPI/newCustomerAPI", body);

    EGS_API_DataContract_Response res = FormJsonSerializer::deserializeObject(classNum(EGS_API_DataContract_Response), responseTxt);
    this.log(XAPI_APIS::CreateCustomer, "CustAccount", res.parmMessage(), responseTxt);
}

public void callInstallationAPI()
{
    Map configMap = new Map(Types::String, Types::String);
    configMap.insert('<DataAreaId>', curExt());
    configMap.insert('<netArea>', curExt());
    var body = this.prepareBody(XAPI_APIS::CreateInstallation, configMap);
    str responseTxt = this.sendPostRequest(resourceUrl + "/api/services/EGS_WebApiServiceAPI/EGS_WebApiSeServiceAPI/newInstallationAPI", body);

    EGS_API_DataContract_Response_Installation res =FormJsonSerializer::deserializeObject(classNum(EGS_API_DataContract_Response_Installation), responseTxt);

    this.log(XAPI_APIS::CreateInstallation, "InstNum", res.parmInstallationNum(), responseTxt);
}

public void callContractAPI(CustAccount _custAccount, str _attachmentNum, str _deliveryCategory)
{
    XAPI_APILogTable lotTable;
    Map configMap = new Map(Types::String, Types::String);

    configMap.insert('<DataAreaId>', curExt());

    select firstonly lotTable
        where lotTable.ApiName == XAPI_APIS::CreateCustomer
        && lotTable.Key == 'CustAccount';

    configMap.insert('<custAccount>', lotTable.Value);

    select firstonly  lotTable
    where lotTable.ApiName == XAPI_APIS::CreateInstallation
        && lotTable.Key == 'InstNum';
    configMap.insert('<InstNum>', lotTable.Value);

    EXU_UtilityInstallation uinst;
    select firstonly uinst
        where uinst.InstNum == lotTable.Value;

    configMap.insert('<deliveryCategory>', uinst.DeliveryCategory);

    var body = this.prepareBody(XAPI_APIS::CreateContract, configMap);
    str responseTxt = this.sendPostRequest(resourceUrl + "/api/services/EGS_WebApiServiceAPI/EGS_WebApiSeServiceAPI/newContractAPI",
        body);

    EGS_API_DataContract_Response res =FormJsonSerializer::deserializeObject(classNum(EGS_API_DataContract_Response), responseTxt);

    this.log(XAPI_APIS::CreateContract, "ContractNum", res.parmMessage(), responseTxt);
}

public void callContractPartAPI(CustAccount _custAccount, str _attachmentNum, str _deliveryCategory, EXU_ContractNum _contractNum, str _productNum)
{
    XAPI_APILogTable logTable;
    Map configMap = new Map(Types::String, Types::String);

    configMap.insert('<DataAreaId>', curExt());

    select firstonly logTable
    where logTable.ApiName == XAPI_APIS::CreateCustomer
       && logTable.Key     == 'CustAccount';
    configMap.insert('<custAccount>', logTable.Value);


    select firstonly logTable
    where logTable.ApiName == XAPI_APIS::CreateContract
       && logTable.Key     == 'ContractNum';
    configMap.insert('<Contract>', logTable.Value);

    select firstonly logTable
    where logTable.ApiName == XAPI_APIS::CreateInstallation
       && logTable.Key     == 'InstNum';
    configMap.insert('<InstNum>', logTable.Value);

    EXU_UtilityInstallation uinst;
    select firstonly uinst
    where uinst.InstNum == logTable.Value;

    configMap.insert('<DeliveryCategory>', uinst.DeliveryCategory);

    select firstonly logTable
    where logTable.ApiName == XAPI_APIS::CreateContract
       && logTable.Key     == 'ProductNum';
    configMap.insert('<ProductNum>', logTable.Value);

    var body = this.prepareBody(XAPI_APIS::CreateContractPart, configMap);

    str responseTxt = this.sendPostRequest(
    resourceUrl + "/api/services/EGS_WebApiServiceAPI/EGS_WebApiSeServiceAPI/newContractPartAPI",
    body);

    EGS_API_DataContract_Response res = FormJsonSerializer::deserializeObject(
    classNum(EGS_API_DataContract_Response), responseTxt);

    this.log(XAPI_APIS::CreateContractPart, "ContractPartNum", res.parmMessage(), responseTxt);
}

public void callMeterReadingAPI(CustAccount _custAccount, str _attachmentNum, str _deliveryCategory, str _meterNum)
{
    XAPI_APILogTable lotTable;
    Map configMap = new Map(Types::String, Types::String);

    configMap.insert('<DataAreaId>', curExt());

    select firstonly lotTable
        where lotTable.ApiName == XAPI_APIS::CreateCustomer
        && lotTable.Key == 'CustAccount';

    configMap.insert('<custAccount>', lotTable.Value);

    select firstonly  lotTable
    where lotTable.ApiName == XAPI_APIS::CreateInstallation
        && lotTable.Key == 'InstNum';
    configMap.insert('<InstNum>', lotTable.Value);

    EXU_UtilityInstallation uinst;
    select firstonly uinst
        where uinst.InstNum == lotTable.Value;

    configMap.insert('<deliveryCategory>', uinst.DeliveryCategory);

    select firstonly lotTable
    where lotTable.ApiName == XAPI_APIS::CreateMeterReading
       && lotTable.Key == 'meterNum';
    configMap.insert('<meterNum>', lotTable.Value);


    var body = this.prepareBody(XAPI_APIS::CreateContract, configMap);
    str responseTxt = this.sendPostRequest(resourceUrl + "/api/services/EGS_WebApiServiceAPI/EGS_WebApiSeServiceAPI/newMeterReadingAPI",
        body);

    EGS_API_DataContract_Response res =FormJsonSerializer::deserializeObject(classNum(EGS_API_DataContract_Response), responseTxt);

    this.log(XAPI_APIS::CreateMeterReading, "MeterNum", res.parmMessage(), responseTxt);
}

private void log(XAPI_APIS _api, str _key, str _value, str _response)
{
    XAPI_APILogTable logTable;

    logTable.clear();
    logTable.ApiName = _api;
    logTable.Key = _key;
    logTable.Value = _value;
    logTable.Response = _response;
    logTable.insert();

}

private str prepareBody(XAPI_APIS _api, Map _fields)
{
    XAPI_APIConfigurations conif;
    select firstonly conif where conif.API == _api;

    str body = conif.JSON;

    MapEnumerator enumerator = _fields.getEnumerator();
    while (enumerator.moveNext())
    {
        str placeholder = enumerator.currentKey();
        str value = enumerator.currentValue();
        body = strReplace(body, placeholder, value);
    }

    return body;
}

public static XAPI_API_CallAutomator construct()
{
    XAPI_API_CallAutomator apiAuto = new XAPI_API_CallAutomator();
    return apiAuto;
}
